/* Soft washes standing in for the original's grainy gradient artwork. Tokens only. */
.growthbook-v2-panel-violet {
  background:
    radial-gradient(90% 70% at 0% 100%, var(--chart-4) 0%, transparent 60%),
    radial-gradient(70% 60% at 100% 20%, color-mix(in oklab, var(--primary) 35%, var(--foreground)) 0%, transparent 70%),
    linear-gradient(165deg, color-mix(in oklab, var(--primary) 85%, var(--card)) 0%, var(--primary) 35%, color-mix(in oklab, var(--primary) 55%, var(--foreground)) 100%);
}
.growthbook-v2-panel-mint {
  background:
    radial-gradient(80% 70% at 100% 0%, var(--chart-4) 0%, transparent 70%),
    linear-gradient(135deg, color-mix(in oklab, var(--chart-4) 35%, var(--card)) 0%, var(--chart-4) 100%);
}
.growthbook-v2-panel-sky {
  background:
    radial-gradient(70% 60% at 0% 0%, var(--chart-5) 0%, transparent 70%),
    radial-gradient(60% 50% at 100% 50%, color-mix(in oklab, var(--primary) 45%, var(--foreground)) 0%, transparent 75%),
    linear-gradient(160deg, var(--glow) 0%, var(--primary) 55%, color-mix(in oklab, var(--glow) 70%, var(--card)) 100%);
}
.growthbook-v2-panel-navy {
  background: linear-gradient(170deg, var(--foreground) 0%, color-mix(in oklab, var(--chart-2) 70%, var(--foreground)) 100%);
}
.growthbook-v2-panel-teal {
  background: linear-gradient(160deg, var(--chart-3) 0%, color-mix(in oklab, var(--chart-3) 45%, var(--chart-4)) 55%, var(--chart-4) 100%);
}

/* In dark themes the foreground is light, so the navy wash starts from the card colour instead. */
.dark .growthbook-v2-panel-navy,
.dark.growthbook-v2-panel-navy {
  background: linear-gradient(170deg, var(--card) 0%, color-mix(in oklab, var(--chart-2) 60%, var(--card)) 100%);
}

import type { ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./growthbook-v2-panel.css";

export interface GrowthbookV2PanelProps {
  /** the wash: violet (default), mint, sky, navy or teal */
  tone?: "violet" | "mint" | "sky" | "navy" | "teal";
  /** faint hairline guides near the edges, as on the original's product frames */
  grid?: boolean;
  /** a real image or video; replaces the wash when given */
  media?: ReactNode;
  /** things placed on top of the wash (e.g. a screenshot frame) */
  children?: ReactNode;
  className?: string;
}

const guides = ["inset-y-0 left-[6%] w-px", "inset-y-0 right-[6%] w-px", "inset-x-0 top-[21%] h-px", "inset-x-0 bottom-[21%] h-px"];

export function GrowthbookV2Panel({ tone = "violet", grid, media, children, className }: GrowthbookV2PanelProps) {
  return (
    <div className={cn("relative isolate overflow-clip rounded-xl", !media && `growthbook-v2-panel-${tone}`, className)}>
      {media ? (
        <div className="absolute inset-0 [&>*]:size-full [&>img]:object-cover [&>video]:object-cover">{media}</div>
      ) : (
        grid && guides.map((g) => <span key={g} aria-hidden className={cn("absolute -z-10 bg-card/25", g)} />)
      )}
      {children}
    </div>
  );
}
